CREATE TABLE b2c_enquiries (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_name TEXT NOT NULL CHECK(length(customer_name)<=255), enquired_date TEXT NOT NULL CHECK(length(CAST(enquired_date AS BLOB))=10 AND enquired_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), requirement TEXT NOT NULL, additional_notes TEXT, mobile_number TEXT CHECK(mobile_number IS NULL OR length(mobile_number)<=20), location TEXT CHECK(location IS NULL OR length(location)<=255), enquiry_type TEXT CHECK(enquiry_type IS NULL OR length(enquiry_type)<=50), status TEXT DEFAULT 'Pending' CHECK(status IS NULL OR length(status)<=50), created_at TEXT NOT NULL CHECK(length(CAST(created_at AS BLOB))=24 AND (created_at GLOB '????-??-??T??:??:??.???Z' AND printf('%017d',CAST(replace(replace(replace(replace(replace(created_at,'-',''),'T',''),':',''),'.',''),'Z','') AS INTEGER))=replace(replace(replace(replace(replace(created_at,'-',''),'T',''),':',''),'.',''),'Z',''))));
CREATE TABLE corporate_enquiries (id INTEGER PRIMARY KEY AUTOINCREMENT, corporate_name TEXT NOT NULL CHECK(length(corporate_name)<=255), enquired_date TEXT NOT NULL CHECK(length(CAST(enquired_date AS BLOB))=10 AND enquired_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), requirement TEXT NOT NULL, additional_notes TEXT, mobile_number TEXT CHECK(mobile_number IS NULL OR length(mobile_number)<=20), location TEXT CHECK(location IS NULL OR length(location)<=255), enquiry_type TEXT CHECK(enquiry_type IS NULL OR length(enquiry_type)<=50), status TEXT DEFAULT 'Pending' CHECK(status IS NULL OR length(status)<=50), created_at TEXT NOT NULL CHECK(length(CAST(created_at AS BLOB))=24 AND (created_at GLOB '????-??-??T??:??:??.???Z' AND printf('%017d',CAST(replace(replace(replace(replace(replace(created_at,'-',''),'T',''),':',''),'.',''),'Z','') AS INTEGER))=replace(replace(replace(replace(replace(created_at,'-',''),'T',''),':',''),'.',''),'Z',''))));
