CREATE TABLE enquiry_followups (id INTEGER PRIMARY KEY AUTOINCREMENT, enquiry_id INTEGER NOT NULL, enquiry_type TEXT NOT NULL CHECK(enquiry_type IN ('b2c','corporate')), followup_number INTEGER NOT NULL CHECK(followup_number BETWEEN 1 AND 3), followup_date TEXT NOT NULL CHECK(length(CAST(followup_date AS BLOB))=10 AND followup_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), followup_status TEXT NOT NULL CHECK(length(followup_status)<=50), description TEXT, created_at TEXT NOT NULL CHECK(length(CAST(created_at AS BLOB))=24 AND (created_at GLOB '????-??-??T??:??:??.???Z' AND printf('%017d',CAST(replace(replace(replace(replace(replace(created_at,'-',''),'T',''),':',''),'.',''),'Z','') AS INTEGER))=replace(replace(replace(replace(replace(created_at,'-',''),'T',''),':',''),'.',''),'Z',''))), updated_at TEXT NOT NULL CHECK(length(CAST(updated_at AS BLOB))=24 AND (updated_at GLOB '????-??-??T??:??:??.???Z' AND printf('%017d',CAST(replace(replace(replace(replace(replace(updated_at,'-',''),'T',''),':',''),'.',''),'Z','') AS INTEGER))=replace(replace(replace(replace(replace(updated_at,'-',''),'T',''),':',''),'.',''),'Z',''))), UNIQUE(enquiry_type,enquiry_id,followup_number));
CREATE INDEX idx_followups_parent ON enquiry_followups(enquiry_type,enquiry_id,followup_number);
CREATE TRIGGER trg_followup_parent_insert BEFORE INSERT ON enquiry_followups BEGIN SELECT CASE WHEN NEW.enquiry_type='b2c' AND NOT EXISTS(SELECT 1 FROM b2c_enquiries WHERE id=NEW.enquiry_id) THEN RAISE(ABORT,'missing_enquiry_parent') WHEN NEW.enquiry_type='corporate' AND NOT EXISTS(SELECT 1 FROM corporate_enquiries WHERE id=NEW.enquiry_id) THEN RAISE(ABORT,'missing_enquiry_parent') END; END;
CREATE TRIGGER trg_followup_parent_update BEFORE UPDATE OF enquiry_id,enquiry_type ON enquiry_followups BEGIN SELECT CASE WHEN NEW.enquiry_type='b2c' AND NOT EXISTS(SELECT 1 FROM b2c_enquiries WHERE id=NEW.enquiry_id) THEN RAISE(ABORT,'missing_enquiry_parent') WHEN NEW.enquiry_type='corporate' AND NOT EXISTS(SELECT 1 FROM corporate_enquiries WHERE id=NEW.enquiry_id) THEN RAISE(ABORT,'missing_enquiry_parent') END; END;
CREATE TRIGGER trg_b2c_followup_delete AFTER DELETE ON b2c_enquiries BEGIN DELETE FROM enquiry_followups WHERE enquiry_type='b2c' AND enquiry_id=OLD.id; END;
CREATE TRIGGER trg_corporate_followup_delete AFTER DELETE ON corporate_enquiries BEGIN DELETE FROM enquiry_followups WHERE enquiry_type='corporate' AND enquiry_id=OLD.id; END;

