CREATE TABLE user_submodules (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, submodule_code TEXT NOT NULL REFERENCES submodules(code) ON UPDATE CASCADE ON DELETE CASCADE, created_at TEXT NOT NULL CHECK(length(CAST(created_at AS BLOB))=24 AND (created_at GLOB '????-??-??T??:??:??.???Z' AND printf('%017d',CAST(replace(replace(replace(replace(replace(created_at,'-',''),'T',''),':',''),'.',''),'Z','') AS INTEGER))=replace(replace(replace(replace(replace(created_at,'-',''),'T',''),':',''),'.',''),'Z',''))), UNIQUE(user_id,submodule_code));
