place(replace(replace(created_at,'-',''),'T',''),':',''),'.',''),'Z',''))), updated_at TEXT NOT NULL CHECK(length(CAST(updated_at AS BLOB))=24 AND (updated_at GLOB '????-??-??T??:??:??.???Z' AND printf('%017d',CAST(replace(replace(replace(replace(replace(updated_at,'-',''),'T',''),':',''),'.',''),'Z','') AS INTEGER))=replace(replace(replace(replace(replace(updated_at,'-',''),'T',''),':',''),'.',''),'Z',''))));
