CREATE TRIGGER trg_service_request_notification AFTER INSERT ON service_requests BEGIN INSERT INTO notifications(type,source_key,payload_json,created_at) VALUES('new-request','new-request:'||NEW.id,json_object('id',NEW.id,'name',NEW.name,'createdAt',NEW.created_at),NEW.created_at) ON CONFLICT(source_key) DO NOTHING; END;
CREATE TRIGGER trg_notification_recipients AFTER INSERT ON notifications BEGIN
 INSERT OR IGNORE INTO notification_recipients(notification_id,admin_user_id)
 SELECT NEW.id,a.id FROM admin_users a
 WHERE a.is_active=1 AND (
  a.role='SUPER_ADMIN' OR (
   (EXISTS(SELECT 1 FROM user_modules um WHERE um.user_id=a.id AND um.module_code=CASE NEW.type WHEN 'new-request' THEN 'CLIENTS' ELSE 'ORGANIZATION' END)
    OR (NOT EXISTS(SELECT 1 FROM user_modules ux WHERE ux.user_id=a.id) AND EXISTS(SELECT 1 FROM role_modules rm WHERE rm.role=a.role AND rm.module_code=CASE NEW.type WHEN 'new-request' THEN 'CLIENTS' ELSE 'ORGANIZATION' END)))
   AND (NOT EXISTS(SELECT 1 FROM user_submodules sx WHERE sx.user_id=a.id) OR EXISTS(SELECT 1 FROM user_submodules us WHERE us.user_id=a.id AND us.submodule_code=CASE NEW.type WHEN 'new-request' THEN 'SERVICE_REQUESTS' ELSE 'STAFF' END))
  )
 );
END;
CREATE TRIGGER trg_invoice_chain_guard BEFORE INSERT ON invoices WHEN NEW.chain_version != (SELECT version FROM invoice_chain_state WHERE id=1) BEGIN SELECT RAISE(ABORT,'invoice_chain_conflict'); END;
CREATE TRIGGER trg_invoice_chain_insert AFTER INSERT ON invoices BEGIN UPDATE invoice_chain_state SET last_invoice_id=NEW.id,last_hash=NEW.invoice_hash,version=version+1,updated_at=NEW.updated_at WHERE id=1; END;
CREATE TRIGGER trg_invoice_chain_update AFTER UPDATE OF invoice_hash ON invoices WHEN (SELECT last_invoice_id FROM invoice_chain_state WHERE id=1)=NEW.id BEGIN UPDATE invoice_chain_state SET last_hash=NEW.invoice_hash,version=version+1,updated_at=NEW.updated_at WHERE id=1; END;
CREATE TRIGGER trg_invoice_chain_delete BEFORE DELETE ON invoices WHEN (SELECT last_invoice_id FROM invoice_chain_state WHERE id=1)=OLD.id BEGIN UPDATE invoice_chain_state SET last_invoice_id=(SELECT id FROM invoices WHERE id!=OLD.id ORDER BY id DESC LIMIT 1),last_hash=(SELECT invoice_hash FROM invoices WHERE id!=OLD.id ORDER BY id DESC LIMIT 1),version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1; END;
CREATE TRIGGER trg_store_counter_insert AFTER INSERT ON stores WHEN NEW.store_code GLOB 'MTCSA[0-9]*' AND length(NEW.store_code)>5 AND substr(NEW.store_code,6) NOT GLOB '*[^0-9]*' BEGIN UPDATE number_counters SET next_value=max(next_value,CAST(substr(NEW.store_code,6) AS INTEGER)+1),updated_at=NEW.created_at WHERE kind='store' AND scope=''; END;
CREATE TRIGGER trg_store_counter_update AFTER UPDATE OF store_code ON stores WHEN NEW.store_code GLOB 'MTCSA[0-9]*' AND length(NEW.store_code)>5 AND substr(NEW.store_code,6) NOT GLOB '*[^0-9]*' BEGIN UPDATE number_counters SET next_value=max(next_value,CAST(substr(NEW.store_code,6) AS INTEGER)+1),updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE kind='store' AND scope=''; END;
CREATE TRIGGER trg_staff_counter_insert AFTER INSERT ON staff WHEN NEW.emp_code GLOB 'MTC[0-9]*' AND length(NEW.emp_code)>3 AND substr(NEW.emp_code,4) NOT GLOB '*[^0-9]*' BEGIN UPDATE number_counters SET next_value=max(next_value,CAST(substr(NEW.emp_code,4) AS INTEGER)+1),updated_at=NEW.created_at WHERE kind='staff' AND scope=''; END;
CREATE TRIGGER trg_staff_counter_update AFTER UPDATE OF emp_code ON staff WHEN NEW.emp_code GLOB 'MTC[0-9]*' AND length(NEW.emp_code)>3 AND substr(NEW.emp_code,4) NOT GLOB '*[^0-9]*' BEGIN UPDATE number_counters SET next_value=max(next_value,CAST(substr(NEW.emp_code,4) AS INTEGER)+1),updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE kind='staff' AND scope=''; END;
